// Ported from the Node app's Sequelize model Asset (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class AssetConfiguration : IEntityTypeConfiguration<Asset>
{
    public void Configure(EntityTypeBuilder<Asset> builder)
    {
        builder.ToTable("assets", t =>
        {
            t.HasCheckConstraint("CK_assets_status", "[status] IN (N'in_use', N'in_store', N'under_repair', N'disposed')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.AssetTag).HasColumnName("asset_tag").HasColumnType("nvarchar(40)").HasMaxLength(40).IsRequired();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(120)").HasMaxLength(120).IsRequired();
        builder.Property(e => e.CategoryId).HasColumnName("category_id");
        builder.Property(e => e.Location).HasColumnName("location").HasColumnType("nvarchar(120)").HasMaxLength(120);
        builder.Property(e => e.PurchaseDate).HasColumnName("purchase_date").HasColumnType("date");
        builder.Property(e => e.Cost).HasColumnName("cost").HasColumnType("decimal(12,2)").HasDefaultValueSql("0");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'in_use'");
        builder.Property(e => e.Notes).HasColumnName("notes").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.HasIndex(e => e.AssetTag).IsUnique();
        builder.HasOne(e => e.InventoryCategory).WithMany(p => p.Assets).HasForeignKey(e => e.CategoryId).OnDelete(DeleteBehavior.NoAction);
    }
}
